import json
data = json.load(open('/app/resources/treasury_bulletin_2010_03.json'))
# Print all keys at the top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print('  ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 1)
    elif isinstance(d, list) and len(d) > 0 and indent < 1:
        print('  ' * indent + f'List with {len(d)} items')
        print_structure(d[0], indent + 1)

print_structure(data)
"

